// i6_restore_oldversion_test.go restores a v2 logical backup archive that was
// produced by a REAL older released binary (built from the git tag, not from
// current main's models) into current main, and proves the old->new restore is
// lossless and fail-closed.
//
// The fixture under testdata/i6-oldversions/<tag>/ was generated by the tag's
// OWN code (scripts/i6-gen/zz_i6gen_test.go.txt applied in a `git worktree add
// <tag>` checkout, run through that tag's runAdminBackup). expected.json is the
// OLD code's canonical record of what it put in the store (the differential
// oracle's "old" side); this test is the "new" side.
//
// What this test DOES verify (task I6, Phase 1 step 2):
//   - the archive extracts, its manifest signature verifies and it LOADS into a
//     current-main-migrated database (SQLite and, when KEYORIX_TEST_PG_DSN is
//     set, PostgreSQL);
//   - every secret version decrypts, under the restored keys and the exact AAD
//     the old binary sealed it with, to the original plaintext recorded in
//     expected.json;
//   - the audit chain of the restored database verifies VALID (the restore
//     command runs verify-audit itself and prints the verdict);
//   - roles, user->role grants, and the user/token/machine-identity/project
//     counts equal what the old code recorded;
//   - a SECOND backup taken by current main of the restored data round-trips
//     again (restore -> re-backup -> restore) and still decrypts.
//
// What this test does NOT verify:
//   - a non-empty audit chain: the generator could not synthesise a valid,
//     linked audit chain at the raw-storage layer it seeds through, so the
//     fixture's audit_events table is empty (an empty chain verifies VALID).
//     Non-empty-chain restore is covered by TestAdminRestore_V0953Archive and
//     TestBackupRestore_PropertyRoundTrip_V1ArchiveOnHEAD, which use archives
//     from real binaries that DID write audit events.
//   - pending key-rotation state and passphrase-change history (the fixture's
//     structural tables are present but empty -- see expected.json "notes").
//   - adversarial corruption: that is TestI6RestoreOldVersion_CorruptFailsClosed
//     (below, full-command no-partial-state) and FuzzI6OldArchiveMutation
//     (internal/backupfmt, the broad mutation space).
//
// Not t.Parallel(): mutates package-level cobra flag vars and os.Chdir, like
// every other test in this package.
package admin

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
	"gorm.io/gorm"

	"github.com/keyorixhq/keyorix/internal/encryption"
	"github.com/keyorixhq/keyorix/internal/i18n"
	"github.com/keyorixhq/keyorix/internal/storage"
	"github.com/keyorixhq/keyorix/internal/storage/models"
)

// i6SecretRecord / i6Grant / i6RoleRec / i6Expected mirror the sidecar schema
// scripts/i6-gen/zz_i6gen_test.go.txt writes (the OLD code's canonical dump).
type i6SecretRecord struct {
	SecretName    string `json:"secret_name"`
	Version       int    `json:"version"`
	Plaintext     string `json:"plaintext"`
	ProjectID     uint   `json:"project_id"`
	SecretID      uint   `json:"secret_id"`
	EnvironmentID uint   `json:"environment_id"`
}

type i6Grant struct {
	UserID   uint   `json:"user_id"`
	Username string `json:"username"`
	RoleID   uint   `json:"role_id"`
	RoleName string `json:"role_name"`
}

type i6RoleRec struct {
	ID   uint   `json:"id"`
	Name string `json:"name"`
}

type i6Expected struct {
	Passphrase           string           `json:"passphrase"`
	Secrets              []i6SecretRecord `json:"secrets"`
	Roles                []i6RoleRec      `json:"roles"`
	Grants               []i6Grant        `json:"grants"`
	UserCount            int              `json:"user_count"`
	TokenCount           int              `json:"token_count"`
	MachineIdentityCount int              `json:"machine_identity_count"`
	ProjectCount         int              `json:"project_count"`
	Notes                string           `json:"notes"`
}

// i6Tags lists every committed old-release fixture directory. Add a directory
// (archive + expected.json) and its tag here to extend coverage to another
// release without touching the test body.
var i6Tags = []string{"v0.96.3"}

func i6FixtureDir(t *testing.T, tag string) string {
	t.Helper()
	wd, err := os.Getwd()
	require.NoError(t, err)
	return filepath.Join(wd, "testdata", "i6-oldversions", tag)
}

func i6LoadExpected(t *testing.T, tag string) i6Expected {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(i6FixtureDir(t, tag), "expected.json"))
	require.NoError(t, err)
	var exp i6Expected
	require.NoError(t, json.Unmarshal(raw, &exp))
	return exp
}

// i6WriteConfig writes a restore target config pointing at the given storage
// block, with the RELATIVE key paths the fixture's manifest recorded
// (dek.key/kek.salt). The caller must already be chdir'd into dir.
func i6WriteConfig(t *testing.T, dir string, storageBlock func(dir string) string) string {
	t.Helper()
	cfgPath := filepath.Join(dir, "keyorix.yaml")
	content := "storage:\n" + storageBlock(dir) +
		"  encryption:\n    enabled: true\n    dek_path: dek.key\n    salt_path: kek.salt\n"
	require.NoError(t, os.WriteFile(cfgPath, []byte(content), 0o600))
	return cfgPath
}

func i6SQLiteBlock(dir string) string {
	return fmt.Sprintf("  type: local\n  database:\n    path: %s\n", filepath.Join(dir, "secrets.db"))
}

func TestI6RestoreOldVersion(t *testing.T) {
	for _, tag := range i6Tags {
		t.Run("SQLite/"+tag, func(t *testing.T) {
			runI6RestoreAndVerify(t, tag, i6SQLiteBlock)
		})
		t.Run("Postgres/"+tag, func(t *testing.T) {
			base := pgAdminTestDSN(t) // skips when KEYORIX_TEST_PG_DSN is unset
			runI6RestoreAndVerify(t, tag, func(string) string {
				return fmt.Sprintf("  type: postgres\n  database:\n    dsn: %q\n", pgAdminIsolatedDatabaseDSN(t, base))
			})
		})
	}
}

// runI6RestoreAndVerify restores tag's fixture into a fresh target, verifies the
// full differential oracle, then round-trips a current-main backup of the
// restored data once more.
func runI6RestoreAndVerify(t *testing.T, tag string, storageBlock func(dir string) string) {
	resetBackupRestoreFlags(t)
	require.NoError(t, i18n.InitializeForTesting())
	exp := i6LoadExpected(t, tag)
	archive := filepath.Join(i6FixtureDir(t, tag), "backup.tar.gz")

	dstDir := t.TempDir()
	chdirTest(t, dstDir)
	configPathFlag = i6WriteConfig(t, dstDir, storageBlock)
	restoreInput = archive
	restoreOverwriteExisting = false
	restoreMaxEntryBytes = 0
	restoreMaxTotalBytes = 0
	t.Setenv("KEYORIX_MASTER_PASSWORD", exp.Passphrase)

	out, err := captureStdout(t, func() error { return runAdminRestore(nil, nil) })
	require.NoError(t, err, "restore output:\n%s", out)
	require.Contains(t, out, "verify-audit on the restored database: VALID",
		"an old-version archive must restore with a VALID audit chain")
	require.NotContains(t, out, "could not derive the audit-checkpoint key")

	cfg, err := loadConfig()
	require.NoError(t, err)
	gdb, err := storage.OpenGormDB(cfg)
	require.NoError(t, err)

	i6AssertRestored(t, gdb, exp)
	closeGormDB(gdb)

	// --- Round-trip: current main re-backs-up the restored data and restores it
	// again into a fresh directory; the secrets must still decrypt. This proves
	// the restored-into-new-schema data is itself backup/restore clean.
	i6RoundTripOnce(t, exp, storageBlock)
}

// i6AssertRestored runs the full differential oracle against the restored DB:
// counts, decrypted secret plaintexts, roles and grants all equal what the OLD
// code recorded in expected.json.
func i6AssertRestored(t *testing.T, gdb *gorm.DB, exp i6Expected) {
	t.Helper()

	// --- Structural counts match the old code's record.
	for table, want := range map[string]int64{
		"users":              int64(exp.UserCount),
		"api_tokens":         int64(exp.TokenCount),
		"machine_identities": int64(exp.MachineIdentityCount),
		"projects":           int64(exp.ProjectCount),
		"roles":              int64(len(exp.Roles)),
		"secret_nodes":       int64(len(uniqueSecretIDs(exp.Secrets))),
		"secret_versions":    int64(len(exp.Secrets)),
	} {
		var n int64
		require.NoError(t, gdb.Table(table).Count(&n).Error)
		require.Equal(t, want, n, "row count in %s after restore", table)
	}

	// --- Every secret version decrypts to its recorded plaintext, under the
	// restored keys and the exact AAD the old binary sealed it with. The
	// current working directory is the restore target (dek.key/kek.salt live
	// here), so baseDir "." resolves the key material correctly.
	cfg, err := loadConfig()
	require.NoError(t, err)
	enc := encryption.NewService(&cfg.Storage.Encryption, ".")
	require.NoError(t, enc.Initialize(exp.Passphrase))
	for _, s := range exp.Secrets {
		var ver models.SecretVersion
		require.NoError(t, gdb.Where("secret_node_id = ? AND version_number = ?", s.SecretID, s.Version).
			First(&ver).Error, "secret %q v%d missing after restore", s.SecretName, s.Version)
		aad := encryption.SecretAAD(s.SecretID, s.ProjectID, s.Version)
		pt, derr := enc.DecryptSecretWithAAD(ver.EncryptedValue, aad)
		require.NoError(t, derr, "secret %q v%d failed to decrypt after old->new restore", s.SecretName, s.Version)
		require.Equal(t, s.Plaintext, string(pt),
			"secret %q v%d decrypted to the wrong plaintext after restore", s.SecretName, s.Version)
	}

	// --- Roles equal the source by id and name.
	for _, r := range exp.Roles {
		var role models.Role
		require.NoError(t, gdb.First(&role, r.ID).Error, "role id=%d missing after restore", r.ID)
		require.Equal(t, r.Name, role.Name, "role id=%d name changed after restore", r.ID)
	}

	// --- User->role grants equal the source: each (user_id, role_id) binding
	// exists and the user still carries the recorded username.
	for _, g := range exp.Grants {
		var cnt int64
		require.NoError(t, gdb.Table("user_roles").
			Where("user_id = ? AND role_id = ?", g.UserID, g.RoleID).Count(&cnt).Error)
		require.Equal(t, int64(1), cnt, "grant user=%d role=%d missing after restore", g.UserID, g.RoleID)
		var user models.User
		require.NoError(t, gdb.First(&user, g.UserID).Error)
		require.Equal(t, g.Username, user.Username, "user id=%d username changed after restore", g.UserID)
	}
}

// TestI6RestoreOldVersion_CorruptFailsClosed proves the FULL admin restore
// command fails closed on a corrupted old-version archive and leaves NO partial
// state: no restored database, and -- critically -- no key material written
// (dek.key/kek.salt). A silent partial restore would be worse than a clean
// refusal, because an operator would believe the restore succeeded.
//
// This drives the whole command (runAdminRestore), so it is the no-key-material
// counterpart to FuzzI6OldArchiveMutation, which fuzzes the broad mutation space
// at the backupfmt extract+load layer (where no key files are written at all).
//
// Most shapes are refused at extraction, before any key staging, so their
// no-key-material check is only meaningful as a floor. "manifest-tamper" is the
// case that gets PAST extraction (a correctly packed archive whose signed
// MANIFEST.json had one byte of created_at changed): it reaches KEK unwrap and
// the manifest-signature gate, and must be refused there with nothing written.
//
// Does NOT verify: that the error MESSAGE is specific to each extraction-stage
// corruption kind (only that it is non-nil and the target is untouched);
// message specificity is covered by the extract/manifest unit tests in
// internal/backupfmt. Only manifest-tamper asserts its message.
func TestI6RestoreOldVersion_CorruptFailsClosed(t *testing.T) {
	wd, err := os.Getwd()
	require.NoError(t, err)
	orig, err := os.ReadFile(filepath.Join(wd, "testdata", "i6-oldversions", "v0.96.3", "backup.tar.gz"))
	require.NoError(t, err)

	tampered := i6TamperManifestCreatedAt(t, orig)

	cases := []struct {
		name    string
		corrupt func(b []byte) []byte
	}{
		{"truncated-half", func(b []byte) []byte { return b[:len(b)/2] }},
		{"truncated-to-1-byte", func(b []byte) []byte { return b[:1] }},
		{"empty", func([]byte) []byte { return nil }},
		{"not-gzip", func(b []byte) []byte {
			out := make([]byte, len(b))
			for i := range out {
				out[i] = 0x41
			}
			return out
		}},
		{"flip-byte-in-stream", func(b []byte) []byte {
			out := make([]byte, len(b))
			copy(out, b)
			out[len(out)/2] ^= 0xFF // corrupts the compressed/pinned bytes -> extract must refuse
			return out
		}},
		{"flip-gzip-magic", func(b []byte) []byte {
			out := make([]byte, len(b))
			copy(out, b)
			out[0] ^= 0xFF
			return out
		}},
		{"manifest-tamper", func([]byte) []byte { return tampered }},
	}
	// Cases that must be refused with a specific message (absent = any error).
	wantErr := map[string]string{"manifest-tamper": "manifest signature is invalid"}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			resetBackupRestoreFlags(t)
			require.NoError(t, i18n.InitializeForTesting())

			dstDir := t.TempDir()
			chdirTest(t, dstDir)
			configPathFlag = i6WriteConfig(t, dstDir, i6SQLiteBlock)

			badPath := filepath.Join(t.TempDir(), "corrupt.tar.gz")
			require.NoError(t, os.WriteFile(badPath, tc.corrupt(orig), 0o600))
			restoreInput = badPath
			restoreOverwriteExisting = false
			restoreMaxEntryBytes = 0
			restoreMaxTotalBytes = 0
			t.Setenv("KEYORIX_MASTER_PASSWORD", i6FixturePassphrase)

			out, rErr := captureStdout(t, func() error { return runAdminRestore(nil, nil) })
			require.Error(t, rErr, "corrupt archive %q must be refused; output:\n%s", tc.name, out)
			if want, ok := wantErr[tc.name]; ok {
				require.ErrorContains(t, rErr, want)
			}

			// No partial state: no database, no key material installed.
			for _, name := range []string{"secrets.db", "dek.key", "kek.salt"} {
				_, statErr := os.Stat(filepath.Join(dstDir, name))
				require.True(t, os.IsNotExist(statErr),
					"corrupt archive %q left %q behind -- restore must not write partial state", tc.name, name)
			}
		})
	}
}

const i6FixturePassphrase = "i6-fixture-pass-7777"

// i6TamperManifestCreatedAt re-packs the archive with the last digit of
// MANIFEST.json's created_at changed and every other entry byte-identical. The
// result is a well-formed gzip/tar whose per-entry sha256 pins all still hold,
// so ExtractArchive accepts it and only the HMAC manifest signature can refuse it.
func i6TamperManifestCreatedAt(t *testing.T, archive []byte) []byte {
	t.Helper()
	zr, err := gzip.NewReader(bytes.NewReader(archive))
	require.NoError(t, err)
	tr := tar.NewReader(zr)
	var buf bytes.Buffer
	zw := gzip.NewWriter(&buf)
	tw := tar.NewWriter(zw)
	tamperedManifest := false
	for {
		hdr, err := tr.Next()
		if err == io.EOF {
			break
		}
		require.NoError(t, err)
		data, err := io.ReadAll(tr)
		require.NoError(t, err)
		if hdr.Name == "MANIFEST.json" {
			var m map[string]any
			require.NoError(t, json.Unmarshal(data, &m))
			ts, ok := m["created_at"].(string)
			require.True(t, ok && len(ts) > 2 && ts[len(ts)-1] == 'Z', "fixture manifest has no UTC created_at string")
			last := ts[len(ts)-2] // the digit before the trailing "Z"
			flipped := byte('0')
			if last == '0' {
				flipped = '1'
			}
			old := []byte(`"created_at": "` + ts + `"`)
			require.Equal(t, 1, bytes.Count(data, old), "created_at must appear exactly once in MANIFEST.json")
			repl := []byte(`"created_at": "` + ts[:len(ts)-2] + string(flipped) + `Z"`)
			data = bytes.Replace(data, old, repl, 1)
			tamperedManifest = true
		}
		hdr.Size = int64(len(data))
		require.NoError(t, tw.WriteHeader(hdr))
		_, err = tw.Write(data)
		require.NoError(t, err)
	}
	require.True(t, tamperedManifest, "fixture archive has no MANIFEST.json")
	require.NoError(t, tw.Close())
	require.NoError(t, zw.Close())
	return buf.Bytes()
}

func uniqueSecretIDs(secrets []i6SecretRecord) map[uint]struct{} {
	ids := make(map[uint]struct{}, len(secrets))
	for _, s := range secrets {
		ids[s.SecretID] = struct{}{}
	}
	return ids
}

// i6RoundTripOnce backs up the just-restored data with CURRENT main, restores
// that fresh archive into a new directory, and re-checks the audit verdict and
// one decrypted secret -- proving the restored data is itself backup clean on
// new code. Precondition: the caller is chdir'd into the first restore target,
// whose dek.key/kek.salt and database are intact.
func i6RoundTripOnce(t *testing.T, exp i6Expected, storageBlock func(dir string) string) {
	t.Helper()

	archive2 := filepath.Join(t.TempDir(), "roundtrip.tar.gz")
	backupOutput = archive2
	require.NoError(t, runAdminBackup(nil, nil), "re-backup of restored data must succeed")

	dst2 := t.TempDir()
	chdirTest(t, dst2)
	configPathFlag = i6WriteConfig(t, dst2, storageBlock)
	restoreInput = archive2
	restoreOverwriteExisting = false
	restoreMaxEntryBytes = 0
	restoreMaxTotalBytes = 0

	out, err := captureStdout(t, func() error { return runAdminRestore(nil, nil) })
	require.NoError(t, err, "second-generation restore output:\n%s", out)
	require.Contains(t, out, "verify-audit on the restored database: VALID",
		"re-backed-up restored data must round-trip with a VALID audit chain")

	cfg, err := loadConfig()
	require.NoError(t, err)
	gdb, err := storage.OpenGormDB(cfg)
	require.NoError(t, err)
	defer closeGormDB(gdb)
	enc := encryption.NewService(&cfg.Storage.Encryption, ".")
	require.NoError(t, enc.Initialize(exp.Passphrase))
	s := exp.Secrets[0]
	var ver models.SecretVersion
	require.NoError(t, gdb.Where("secret_node_id = ? AND version_number = ?", s.SecretID, s.Version).First(&ver).Error)
	pt, err := enc.DecryptSecretWithAAD(ver.EncryptedValue, encryption.SecretAAD(s.SecretID, s.ProjectID, s.Version))
	require.NoError(t, err)
	require.Equal(t, s.Plaintext, string(pt), "secret must still decrypt after a full old->new->new round trip")
}
